def teach(concept: str, theme: str = "") -> dict[str, str]:
    """Return plain/code/remember/mistake for a concept title."""
    blob = f"{concept} {theme}".lower()
    # Course text uses British spelling; the bank keys use American. Normalise once
    # here instead of doubling every key.
    for brit, amer in (("isation", "ization"), ("ising", "izing"), ("iser", "izer"),
                       ("ised", "ized"), ("yse", "yze"), ("ialise", "ialize")):
        blob = blob.replace(brit, amer)
    for entry in BANK:
        for key in entry["keys"]:
            if key in blob:
                return {
                    "plain": entry["plain"],
                    "code": entry["code"],
                    "remember": entry["remember"],
                    "mistake": entry["mistake"],
                }
    return {
        "plain": (
            f"Today's idea — **{concept}** — sits inside the theme of {theme or 'applied AI'}. "
            "Read it as a tool, not trivia: what job does it do, what does it assume about your data, "
            "and what breaks when that assumption is false?"
        ),
        "code": (
            f"# Explore: {concept}\n"
            f'print("practice: {concept}")\n'
            "\n"
            "# Write three lines here that make the idea concrete on data you already have.\n"
            "# If you cannot, you have not understood it yet — go back to the notes."
        ),
        "remember": f"State one assumption `{concept}` makes about your data before you use it.",
        "mistake": f"Copy-pasting `{concept}` from a tutorial without knowing what it assumes or when it fails.",
    }


def _self_check() -> None:
    hit = teach("Broadcasting rules", "NumPy foundations")
    assert "broadcast" in hit["plain"].lower(), hit["plain"]
    miss = teach("Some entirely unmatched concept xyzzy", "nothing")
    assert "xyzzy" in miss["remember"]
    for entry in BANK:
        assert entry["keys"] and entry["plain"] and entry["code"], entry
        compile(entry["code"], "<bank>", "exec")   # every snippet must at least parse
    print(f"teach.py ok — {len(BANK)} bank entries, all snippets parse")


if __name__ == "__main__":
    _self_check()
